from django.db import migrations, models
from django.utils import timezone


def backfill_reading_sessions(apps, schema_editor):
    """Keep the one reading date that existed before sessions: Book.last_read_at.

    Only the latest date per book was ever stored and the pages read on that day
    are unknown, so each backfilled session has from_page == to_page.
    """
    Book = apps.get_model('base', 'Book')
    ReadingSession = apps.get_model('base', 'ReadingSession')
    ReadingSession.objects.bulk_create(
        ReadingSession(
            book=book,
            date=timezone.localtime(book.last_read_at).date(),
            from_page=book.current_page,
            to_page=book.current_page,
        )
        for book in Book.objects.exclude(last_read_at=None)
    )


